import shutil
from context import ROOT,SOURCE,STUDY,read,write,sha
def main():
    assert not STUDY.exists();STUDY.mkdir();prior=STUDY.parent/'prefilter_holdout_v1';assert (prior/'checkpoint-index.json').exists()
    for n in ['pose_estimator.py','pose_core.py','pinhole.py']:shutil.copy2(prior/'source_snapshot'/n,SOURCE/n)
    write(STUDY/'test-plan.json',dict(question='Can a spawned image-only worker decouple estimation from the producer and enforce bounded latest-frame transport and simulator-time freshness?',scope='Zero native robot trials. Actual frozen RGB estimator runs in a child process on saved static images;manufactured slow/error/dead-worker/clock cases test IPC only. No controller or hardware deadline qualification.',transport='Two shared-memory input slots withFREE/WRITING/READY/READINGstates,one latest pending bundle,one worker,and one compact result mailbox. Parent publication and polling use try-locks and do not call inference. Parent still copiesRGBand may experience OS latency;no hard8ms claim. One producer thread and one worker per broker.',time='Carry exact simulator capture timestamps and separate host compute time. Delivery requires now_sim>=capture+declared minimum latency and age<=declared maximum. Test policies are explicit hypotheses,not selected sensor rates/deadlines. Reject backward clocks,replayed/wrong-format inputs,stale/foreign outputs and worker death. Never invent covariance or clear grasp membership.',gates='All functional controls must pass,live workerPID differs from producer,latest-only overload drops pending bundles instead of building a queue,actual worker outputs match saved selected poses. Preserve every failed attempt. No native simulator/device/actuator API is imported by broker/worker.',source_index_sha256=sha(prior/'checkpoint-index.json'),assembly_deferred=True))
if __name__=='__main__':main()
